        />
      )}
    </>
  ) : (
    <QuickActionContent icon={icon} title={title} actionId={actionId} />
  );

  if (href) {
    return (
      <Link
        basePath={basePath}
        href={href}
        className={className}
        aria-label={props["aria-label"] ?? (compact ? title : undefined)}
      >
        {content}
      </Link>
    );
  }

  return (
    <button
      className={className}
      {...props}
      onClick={onClick}
      aria-label={props["aria-label"] ?? (compact ? title : undefined)}
    >
      {content}
    </button>
  );
}

