      <Collapsible open={isExpanded} onOpenChange={setIsExpanded}>
        <div
          className={cn(
            "w-full flex items-center gap-2",
            isPanel ? "px-4 py-2" : "px-2 py-1",
            isPanel && isExpanded && "border-b border-gray-200",
          )}
        >
          <CardHeader
            className={cn(
              "w-full flex flex-row items-center justify-between p-0",
              isPanel ? "gap-3 space-y-0" : "pl-2",
            )}
          >
            <CardTitle
              className={
                isPanel
                  ? "text-sm font-bold uppercase tracking-wide text-gray-600"
                  : "text-base mt-1"
              }
            >
              {t(title)}
              {!isPanel && ":"}
            </CardTitle>
            <div
              className={cn(
                isPanel
                  ? "flex shrink-0 items-center gap-1"
                  : "flex rounded-md border border-gray-500 lg:border-0 lg:divide-x-0 mt-1",
                !isPanel &&
                  (editLink || actionButton) &&
                  "divide-x divide-gray-500",
              )}
            >
              {!readOnly && editLink && (
                <div className="flex">
                  <Button
                    asChild
                    variant="ghost"
                    size="icon"
                    className="hover:bg-transparent text-gray-500 hover:text-gray-500"
                  >
                    <Link href={editLink} aria-label={t("edit")}>
                      <SquarePen className="size-4" />
                    </Link>
                  </Button>
                </div>
              )}
              <div className="flex">{actionButton && actionButton}</div>
              <div className="flex">
                <CollapsibleTrigger asChild>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="hover:bg-transparent text-gray-500 hover:text-gray-500"
                    aria-label={isExpanded ? t("collapse") : t("expand")}
                  >
                    {isExpanded ? (
                      <ChevronsDownUp className="size-4 text-gray-500" />
                    ) : (
                      <ChevronsUpDown className="size-4 text-gray-500" />
                    )}
                  </Button>
                </CollapsibleTrigger>
              </div>
            </div>
          </CardHeader>
        </div>

        <CollapsibleContent>
          <CardContent className={isPanel ? "p-4" : "p-2"}>
            {children}
          </CardContent>
        </CollapsibleContent>
      </Collapsible>
    </Card>
  );
}
  const isStructured = !item.questionnaire;
