                    : "text-base font-medium",
                  onTitleClick &&
                    !isEnteredInError &&
                    "cursor-pointer hover:bg-gray-100 rounded px-1.5 py-0.5",
                )}
                onClick={(e) => {
                  if (
                    item.questionnaire?.id &&
                    onTitleClick &&
                    !isEnteredInError
