                onClick={(e) => {
                  if (
                    item.questionnaire?.id &&
                    onTitleClick &&
                    !isEnteredInError
                  ) {
                    e.stopPropagation();
                    onTitleClick(item.questionnaire.id);
                  }
                }}
              >
                {title}
              </CardTitle>
