          <PopoverTrigger asChild>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="size-9 shrink-0"
              aria-label={t("more_actions")}
            >
              <DotsVerticalIcon aria-hidden="true" />
            </Button>
          </PopoverTrigger>
          <PopoverContent
            align="end"
            aria-label={t("encounter_actions")}
            className="w-80 max-w-[calc(100vw-2rem)] space-y-2 p-2"
          >
            <div
              role="group"
              aria-label={t("appointment")}
              className="flex flex-wrap items-center gap-1"
            >
              {appointmentActions}
            </div>
            {canWritePrimaryEncounter && (
              <div className="border-t border-gray-200 pt-2">
                {encounterActions}
              </div>
            )}
          </PopoverContent>
        </Popover>
      ) : (
        encounterActions
      )}
    </div>
  );
};

const AppointmentEncounterHeaderActions = ({
  encounter,
  onStart,
  onComplete,
  onCloseAppointment,
  isPending,
}: {
  encounter: EncounterRead;
  onStart: () => void;
  onComplete: () => void;
  onCloseAppointment: () => void;
  isPending: boolean;
}) => {
  const { t } = useTranslation();
  const requiresDischarge = encounterRequiresDischarge(encounter);

  if (
    encounter.status === EncounterStatus.PLANNED ||
    encounter.status === EncounterStatus.ON_HOLD
  ) {
    return (
      <div
        role="group"
        aria-label={t("encounter_actions")}
        className="flex min-w-0 flex-wrap items-center gap-1"
      >
        <Button
          type="button"
          variant="outline"
          className="h-auto min-h-8 max-w-full whitespace-normal border-gray-300 px-3 py-1.5 text-sm shadow-none"
          onClick={onStart}
        >
          {t("start_encounter")}
        </Button>
      </div>
    );
  }

  return (
    <div
      role="group"
      aria-label={t("encounter_actions")}
      className="flex min-w-0 flex-wrap items-center gap-1"
    >
      <Button
        type="button"
        variant="outline"
        className="h-auto min-h-8 max-w-full gap-1.5 whitespace-normal border-gray-300 px-3 py-1.5 text-sm shadow-none"
        disabled={isPending}
        onClick={onComplete}
      >
        <CheckCircle aria-hidden="true" />
        {requiresDischarge ? t("mark_for_discharge") : t("complete")}
      </Button>
      {encounter.status !== EncounterStatus.COMPLETED && (
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="size-8 shrink-0"
              aria-label={t("more_actions")}
            >
              <DotsVerticalIcon className="text-gray-700" aria-hidden="true" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent className="max-w-[calc(100vw-2rem)]" align="end">
            {encounter.appointment?.status !== AppointmentStatus.FULFILLED && (
              <DropdownMenuItem
                className="p-2.5"
                onClick={onCloseAppointment}
                disabled={isPending}
              >
                <div className="flex flex-col items-start">
                  <span className="text-sm font-medium text-black">
                    {t("close_appointment")}
                  </span>
                  <p className="text-xs text-gray-700">
                    {t("close_appointment_description")}
                  </p>
                </div>
              </DropdownMenuItem>
            )}
            <DropdownMenuItem
              className="p-2.5"
              onClick={onComplete}
              disabled={isPending}
            >
              <div className="flex flex-col items-start">
                <span className="text-sm font-medium text-black">
                  {requiresDischarge
                    ? t("mark_for_discharge")
                    : t("mark_as_complete")}
                </span>
                <p className="text-xs text-gray-700">
                  {requiresDischarge
                    ? t("mark_for_discharge_description")
                    : t("mark_as_complete_description")}
                </p>
              </div>
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </div>
  );
};

